        out[0][0] = path
        seen = {(0, 0)}
        stack = [(0, 0)]
        while stack:
            x, y = stack[-1]
            ns = [(x+dx, y+dy) for dx, dy in order
                  if 0 <= x+dx < 20 and 0 <= y+dy < 20
                  and (x+dx, y+dy) not in seen]
            if not ns:
                stack.pop()
                continue
            if method == 0:
                nx, ny = rng.choice(ns)
                seen.add((nx, ny))
                if ny < h and nx < w and grid[ny][nx] != path:
                    return None
                out[ny][nx] = path
                stack.append((nx, ny))
            else:
                rng.shuffle(ns)
                moved = False
                for nx, ny in ns:
                    if (nx, ny) not in seen:
                        seen.add((nx, ny))
                        if ny < h and nx < w and grid[ny][nx] != path:
                            return None
                        out[ny][nx] = path
                        stack.append((nx, ny))
                        moved = True
                        break
                if not moved:
                    stack.pop()
