def transform(grid):
    h, w = len(grid), len(grid[0])
    path = grid[0][0]
    wall = next(v for row in grid for v in row if v != path)
    target = [[v == path for v in row] for row in grid]
    deadline = time.time() + 8.0
    base = ((0,1),(1,0),(0,-1),(-1,0))
    common = [0,1,2,3,4,5,7,8,10,11,12,13,20,21,22,23,24,25,
              42,43,44,123,1234,2023,2024,2025,1337]

    def attempt(seed, order, kind):
        rng = random.Random(seed)
        out = [[False]*20 for _ in range(20)]
        out[0][0] = True
        seen = {(0,0)}
        stack = [(0,0)]
        while stack:
            x,y = stack[-1]
            ds = list(order)
            rng.shuffle(ds)
            moved = False
            for dx,dy in ds:
                nx,ny = x+dx,y+dy
                if not (0 <= nx < 20 and 0 <= ny < 20) or (nx,ny) in seen:
                    continue
                seen.add((nx,ny))
                if kind == 0:
                    take = rng.random() < .5
                elif kind == 1:
                    take = rng.choice((True,False))
                elif kind == 2:
                    take = rng.randrange(2) == 0
                else:
