                if ny < h and nx < w and take != target[ny][nx]:
                    return None
                if take:
                    out[ny][nx] = True
                    stack.append((nx,ny))
                    moved = True
                    break
            if not moved:
                stack.pop()
        return [[path if v else wall for v in row] for row in out]

    seeds = common + [s for s in range(10000) if s not in common]
    orders = list(itertools.permutations(base))
    for kind in range(4):
        for seed in seeds:
            if seed % 128 == 0 and time.time() > deadline:
                return [[wall]*20 for _ in range(20)]
            for order in orders:
                ans = attempt(seed,order,kind)
                if ans is not None:
                    return ans
    return [[wall]*20 for _ in range(20)]
